"""
4-colouring of complete graphs without monochromatic triangles.
Uses the Greenwood-Gleason construction over GF(16) to get K_32,
then attempts to extend to larger n via backtracking CSP with
constraint propagation and iterative vertex extension.
"""
import time

def construct():
    start_time = time.time()
    deadline = start_time + 110.0

    # GF(16) arithmetic: field generated by x^4 + x + 1 (primitive polynomial)
    # Elements are 4-bit integers 0..15.
    def gf16_mul(a, b):
        r = 0
        for i in range(4):
            if (b >> i) & 1:
                r ^= a << i
        for i in range(7, 3, -1):
            if (r >> i) & 1:
                r ^= 0b10011 << (i - 4)
        return r

    # Build log table
    log = {}
    x = 1
    for e in range(15):
        log[x] = e
        x = gf16_mul(x, 2)

    # Base K32 coloring
    colors = []
    for i in range(32):
        for j in range(i + 1, 32):
            if i // 16 == j // 16:
                colors.append(log[i ^ j] % 3)
            else:
                colors.append(3)

    n = 32

    # Build adjacency: adj[v][c] = set of u such that edge(v,u) has color c
    adj = [[set() for _ in range(4)] for _ in range(n)]
    idx = 0
    for i in range(n):
        for j in range(i + 1, n):
            c = colors[idx]
            adj[i][c].add(j)
            adj[j][c].add(i)
            idx += 1

    def solve_new_vertex(adj, n, allowed_colors, deadline):
        """Find colors for a new vertex connected to n existing vertices.
        Constraint: for any color c, the set of vertices u with edge(new,u)=c
        must be an independent set in the graph (V, E_c) where E_c is the
        color-c edges among existing vertices.
        """
        assignment = [-1] * n

        # Precompute: for each vertex v and color c, the set of "conflicting"
        # vertices: if new-v has color c, then new-u cannot have color c
        # for any u in adj[v][c].
        # We'll use this during backtracking.

        # Variable ordering: most constrained first
        order = list(range(n))
        order.sort(key=lambda v: len(allowed_colors[v]))

        def backtrack(idx):
            if time.time() > deadline:
                return None
            if idx == n:
                return assignment[:]

            v = order[idx]
            for c in allowed_colors[v]:
                # Check consistency with already-assigned vertices
                valid = True
                for prev_idx in range(idx):
                    u = order[prev_idx]
                    cu = assignment[u]
                    if cu == c:
                        # If new-u and new-v both have color c,
                        # then u and v must NOT be adjacent in color c
                        if v in adj[u][c]:
                            valid = False
                            break
                if not valid:
                    continue

                assignment[v] = c
                res = backtrack(idx + 1)
                if res is not None:
                    return res
                assignment[v] = -1
            return None

        return backtrack(0)

    # Iteratively extend
    max_n = n
    max_colors = colors[:]

    for attempt in range(50):
        if time.time() > deadline - 3.0:
            break

        # All 4 colors allowed for each edge from new vertex
        allowed = [[0, 1, 2, 3] for _ in range(n)]

        sol = solve_new_vertex(adj, n, allowed, deadline)

        if sol is None:
            break

        # Verify the solution
        valid = True
        for c in range(4):
            # Get vertices connected to new vertex with color c
            verts = [i for i in range(n) if sol[i] == c]
            # Check no two are adjacent in color c
            for ai in range(len(verts)):
                for bi in range(ai + 1, len(verts)):
                    if verts[bi] in adj[verts[ai]][c]:
                        valid = False
                        break
                if not valid:
                    break
            if not valid:
                break

        if not valid:
            break

        # Accept and update
        new_n = n + 1
        new_colors = colors[:] + sol

        # Update adjacency
        new_adj = [[set() for _ in range(4)] for _ in range(new_n)]
        for i in range(n):
            for c in range(4):
                new_adj[i][c] = adj[i][c].copy()
            new_adj[i][sol[i]].add(n)
        for c in range(4):
            new_adj[n][c] = set()
        for i in range(n):
            new_adj[n][sol[i]].add(i)

        n = new_n
        colors = new_colors
        adj = new_adj
        max_n = n
        max_colors = colors[:]

    return {'n': max_n, 'colors': max_colors}
